def norm(word: str) -> str:
    word = word.strip().replace("ك", "ک").replace("ي", "ی").replace("ى", "ی").replace("\u200c", " ")
    return re.sub(r"\s+", " ", word).lower()


def parse(raw: str, category: str, level: int) -> list[str]:
    values = [part.strip() for part in raw.replace("|", "\n").splitlines() if part.strip()]
    unique = []
    seen = set()
    for value in values:
        key = norm(value)
        if key not in seen:
            unique.append(value)
            seen.add(key)
    if len(unique) < 100:
        raise SystemExit(f"{category} level {level}: only {len(unique)} unique candidates")
    return unique[:100]


def main() -> None:
    data = json.loads(BANK.read_text(encoding="utf-8"))
    additions = {
        "places": {"1": parse(PLACES_EASY, "places", 1), "2": parse(PLACES_MEDIUM, "places", 2), "3": parse(PLACES_HARD, "places", 3)},
        "technology": {"1": parse(TECH_EASY, "technology", 1), "2": parse(TECH_MEDIUM, "technology", 2), "3": parse(TECH_HARD, "technology", 3)},
    }
    data.update(additions)
    BANK.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print("Added 600 unique places/technology entries; 100 per category and difficulty.")
    for category, levels in additions.items():
        for level, words in levels.items():
            print(f"{category} level {level}: {len(words)}; first={words[0]}; last={words[-1]}")

if __name__ == "__main__":
    main()
